UPDATE ai_memory_summary_watermark SET revision=revision+1,commit_revision=commit_revision+1,covered_through=#{last}
  WHERE tenant_id=#{row.tenantId} AND scope_key=#{row.scopeKey} AND revision=#{row.revision} AND commit_revision=#{expectedCommit}
   AND covered_through<#{last} AND deletion_epoch=#{row.deletionEpoch}

mapper.sql:
CAST(m.tenant_id AS BINARY)=#{tenant} AND CAST(c.tenant_id AS BINARY)=#{tenant} AND CAST(r.tenant_id AS BINARY)=#{tenant}
  AND CAST(c.user_id AS BINARY)=#{user} AND CAST(c.id AS BINARY)=#{session} AND CAST(r.conversation_id AS BINARY)=#{session}
  AND c.status IN ('ACTIVE','ARCHIVED') AND LOWER(m.role) IN ('user','assistant')

mapper.update:
UPDATE ai_memory_summary_plan SET transport_fingerprint=#{fingerprint}
  WHERE tenant_id=#{tenant} AND scope_key=#{scope} AND id=#{id} AND state='FROZEN'
   AND (transport_fingerprint IS NULL OR transport_fingerprint=#{fingerprint})
